UPDATE HUB_PLAN
SET STATUS = #{status, jdbcType=VARCHAR}
WHERE TRIP_ID = #{tripId, jdbcType=VARCHAR}
RETURNING HUB_PLAN_ID

SELECT TRIP_ID
FROM HUB_PLAN
WHERE HUB_PLAN_ID = #{hubPlanId, jdbcType=VARCHAR}

SELECT HP.HUB_PLAN_ID as "hubPlanId", HP.TRIP_ID as "tripId", T.NAME as "tripName", HP.MEMBER_ID as "memberId", M.NICKNAME as "nickname", HP.LIKE_COUNT as "likeCount", HP.COPY_COUNT as "copyCount", HP.CREATE_DATE as "createdDate",
(CAST(T.END_DATE AS DATE) - CAST(T.START_DATE AS DATE)) as "nights",
( SELECT JSON_AGG(HPK.KEYWORD_ID) FROM HUB_PLAN_KEYWORD HPK WHERE HPK.HUB_PLAN_ID = HP.HUB_PLAN_ID ) as "rawKeywordIds" FROM HUB_PLAN HP JOIN TRIP T ON HP.TRIP_ID = T.TRIP_ID JOIN MEMBER M ON HP.MEMBER_ID = M.MEMBER_ID JOIN REGION R ON T.REGION_ID = R.REGION_ID WHERE HP.STATUS = 'ACTIVE'
AND M.NICKNAME LIKE '%' || #{nickname, jdbcType=VARCHAR} || '%'
AND T.NAME LIKE '%' || #{name, jdbcType=VARCHAR} || '%'
AND (
OR T.REGION_ID IN
#{rid}
OR R.ZDO_CODE IN
#{zdo, jdbcType=INTEGER}
)
AND (CAST(T.END_DATE AS DATE) - CAST(T.START_DATE AS DATE)) >= #{minNights}
AND (CAST(T.END_DATE AS DATE) - CAST(T.START_DATE AS DATE)) <= #{maxNights}
AND HP.HUB_PLAN_ID IN ( SELECT HUB_PLAN_ID FROM HUB_PLAN_KEYWORD WHERE KEYWORD_ID IN
#{kid}
GROUP BY HUB_PLAN_ID HAVING COUNT(DISTINCT KEYWORD_ID) = #{keywordCount} )
ORDER BY HP.LIKE_COUNT DESC ORDER BY HP.COPY_COUNT DESC ORDER BY HP.CREATE_DATE DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM HUB_PLAN HP
    JOIN TRIP   T ON HP.TRIP_ID   = T.TRIP_ID
    JOIN MEMBER M ON HP.MEMBER_ID = M.MEMBER_ID
    JOIN REGION R ON T.REGION_ID  = R.REGION_ID
WHERE HP.STATUS = 'ACTIVE'


    AND M.NICKNAME LIKE '%' || #{nickname, jdbcType=VARCHAR} || '%'



    AND T.NAME LIKE '%' || #{name, jdbcType=VARCHAR} || '%'



    AND (


                OR T.REGION_ID IN

                    #{rid}



                OR R.ZDO_CODE IN

                    #{zdo, jdbcType=INTEGER}



    )



    AND (CAST(T.END_DATE AS DATE) - CAST(T.START_DATE AS DATE)) >= #{minNights}


    AND (CAST(T.END_DATE AS DATE) - CAST(T.START_DATE AS DATE)) <= #{maxNights}



    AND HP.HUB_PLAN_ID IN (
        SELECT HUB_PLAN_ID
        FROM   HUB_PLAN_KEYWORD
        WHERE  KEYWORD_ID IN

            #{kid}

        GROUP BY HUB_PLAN_ID
        HAVING COUNT(DISTINCT KEYWORD_ID) = #{keywordCount}
    )

SELECT HP.HUB_PLAN_ID as "hubPlanId", HP.LIKE_COUNT as "likeCount", HP.COPY_COUNT as "copyCount", M.NICKNAME as "nickname", M.PROFILE_IMAGE as "profileImage",
CASE WHEN LP.MEMBER_ID IS NOT NULL THEN TRUE ELSE FALSE END as "isLiked",
CASE WHEN CP.MEMBER_ID IS NOT NULL THEN TRUE ELSE FALSE END as "isCopied" FROM HUB_PLAN HP JOIN MEMBER M ON HP.MEMBER_ID = M.MEMBER_ID LEFT JOIN LIKE_PLAN LP ON HP.HUB_PLAN_ID = LP.HUB_PLAN_ID AND LP.MEMBER_ID = #{memberId, jdbcType=VARCHAR} AND LP.STATUS = 'ACTIVE' LEFT JOIN COPY_PLAN CP ON HP.HUB_PLAN_ID = CP.HUB_PLAN_ID AND CP.MEMBER_ID = #{memberId, jdbcType=VARCHAR} AND CP.STATUS = 'ACTIVE' WHERE HP.HUB_PLAN_ID = #{hubPlanId, jdbcType=VARCHAR}

SELECT HPK.KEYWORD_ID
FROM   HUB_PLAN_KEYWORD HPK
WHERE  HPK.HUB_PLAN_ID = #{hubPlanId, jdbcType=VARCHAR}

SELECT COUNT(*)
FROM   LIKE_PLAN
WHERE  HUB_PLAN_ID = #{hubPlanId, jdbcType=VARCHAR}
    AND  MEMBER_ID   = #{memberId,  jdbcType=VARCHAR}

