    AND  MEMBER_ID   = #{memberId,  jdbcType=VARCHAR}

UPDATE HUB_PLAN
SET    LIKE_COUNT = GREATEST(LIKE_COUNT + #{delta, jdbcType=INTEGER}, 0)
WHERE  HUB_PLAN_ID = #{hubPlanId, jdbcType=VARCHAR}

